INSERT INTO knowledge_article (id, title, category_id, author_id, author_name, summary, content, cover_img, tags, status, read_count, published_at, created_at, updated_at, deleted) VALUES
(1001, '焦虑调节：使用情绪日记理解自己的感受', 101, 201, '演示管理员', '本文围绕考试前紧张和上台发言害怕等常见学生心理场景，介绍腹式呼吸、担忧时间和证据记录法等可操作方法，帮助使用者识别状态、稳定情绪并逐步恢复日常节奏。', '
## 分类
焦虑调节

## 摘要
本文围绕考试前紧张和上台发言害怕等常见学生心理场景，介绍腹式呼吸、担忧时间和证据记录法等可操作方法，帮助使用者识别状态、稳定情绪并逐步恢复日常节奏。

## 适用场景
- 考试前紧张
- 上台发言害怕
- 希望通过简单练习改善当前状态
- 需要为咨询或自我反思整理问题

## 正文

### 1. 先识别当前状态
当出现考试前紧张时，可以先暂停对自己的批评，把注意力放在“我现在发生了什么”上。建议记录三个信息：当时的事件、脑海中最强烈的想法、身体上最明显的反应。这样做不是为了立刻消除情绪，而是帮助自己从混乱感中退后一步，看清楚压力或情绪的来源。

### 2. 使用可执行的小步骤
面对上台发言害怕，不要一开始就要求自己完全恢复。可以先选择一个 5 到 10 分钟内能完成的小行动，例如整理桌面、写下任务清单、喝水、短暂散步或给可信任的人发一条消息。小步骤可以降低启动难度，让大脑重新获得掌控感。

### 3. 练习腹式呼吸
腹式呼吸适合在情绪强度较高时使用。练习时先找到一个相对安静的位置，保持自然坐姿或站姿，把注意力放在呼吸、身体触感或眼前可见的物品上。如果注意力被担忧带走，只需要温和地把它带回来，不需要责备自己。

### 4. 结合担忧时间和证据记录法
单一方法不一定适合所有情况。可以把担忧时间用于梳理问题，把证据记录法用于放松身体或安排下一步行动。持续记录几天后，通常能更清楚地看到哪些方法对自己更有效。

## 注意事项
本资料仅用于心理健康科普和系统测试，不能替代专业诊断或治疗。如果出现持续绝望、自伤想法、明显失控、长时间无法睡眠或难以维持正常学习生活等情况，应及时联系学校心理中心、专业心理咨询师或当地紧急求助资源。

## 关键词
焦虑调节、考试前紧张、腹式呼吸、大学生心理健康
