身体扫描适合在情绪强度较高时使用。练习时先找到一个相对安静的位置，保持自然坐姿或站姿，把注意力放在呼吸、身体触感或眼前可见的物品上。如果注意力被担忧带走，只需要温和地把它带回来，不需要责备自己。

### 4. 结合腹式呼吸和担忧时间
单一方法不一定适合所有情况。可以把腹式呼吸用于梳理问题，把担忧时间用于放松身体或安排下一步行动。持续记录几天后，通常能更清楚地看到哪些方法对自己更有效。

