(1012, '焦虑调节：面对成绩比较时如何稳定心态', 101, 201, '演示管理员', '本文围绕担心未来结果和心慌和坐立不安等常见学生心理场景，介绍担忧时间、证据记录法和小步暴露等可操作方法，帮助使用者识别状态、稳定情绪并逐步恢复日常节奏。', '
